/**
 * A picture opened large over the page (`design/components/lightbox.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/lightbox.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import * as zag from '@zag-js/dialog'

import {
  MEMBER_PROVIDERS,
  Portal,
  Ref,
  SlotOutlet,
  SlotTemplate,
  Spread,
  agentMember,
  cell,
  derived,
  elementRef,
  mergeParts,
  modalFocusTarget,
  mountEffect,
  normalizeProps,
  setup,
  uniqueId,
  useDirection,
  useMachine,
  useMember,
  watchEffect,
  type Each,
} from '@polymorph/angular'
import { usePresence } from '@polymorph/angular/motion'
import styles from '@polymorph/recipes/overlays/lightbox.module.css'
import { Button, type ButtonProps } from '../controls/Button'
import { Image, type ImageProps } from '../structure/Image'

export interface LightboxImage {
  src: string
  alt: string
}

export interface LightboxMessages {
  close: string
  previous: string
  next: string
  position: (position: number, count: number) => string
}

/** A picture opened large over the page: the inputs it takes, by the React member's prop names. */
export interface LightboxProps {
  /**
   * The picture shown first while the lightbox holds the position. Defaults to 0.
   */
  defaultIndex?: number
  defaultOpen?: boolean
  /**
   * The pictures in reading order. An empty list opens nothing.
   */
  images: LightboxImage[]
  /**
   * The picture shown, counted from 0. Controlled, as in Carousel.
   */
  index?: number
  /**
   * The dialog's accessible name, such as "Attachment preview". It is not drawn.
   */
  label: string
  /**
   * Omit for the English defaults; localized hosts pass their own.
   */
  messages?: LightboxMessages
  open?: boolean
}

/** A picture opened large over the page. */
@Component({
  selector: 'pm-lightbox',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Portal, Ref, SlotOutlet, SlotTemplate, Spread, Button, Image],
  // prettier-ignore
  template: `<ng-template pmSlot="trigger" [pmSlotOf]="$"><ng-content select="[slot=trigger]" /></ng-template>
<ng-container [pmSlotOutlet]="'trigger'" [pmSlotOf]="$" />
<ng-template pmPortal>@if (e1()) {<!-- scrim -->
<div
[pmSpread]="e2()"
[pmRef]="scrim"
></div>}
@if (e3()) {<div
[pmSpread]="e4()"
><!-- panel -->
<div
[pmSpread]="e5()"
[pmRef]="panel"
><!-- title -->
<h2
[pmSpread]="e6()"
>{{ e7() }}</h2>
<!-- stage -->
<div
[attr.class]="e8()"
>@for (picture of e9(); track e10()) {<pm-image
[src]="e11(picture)"
[alt]="e12(picture)"
loading="eager"
></pm-image>}</div>
@if (e13()) {<!-- previous -->
<div
[attr.class]="e14()"
data-lightbox-part="previous"
><pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e15()"
icon="previous"
[label]="e16()"
[disabled]="e17()"
(click)="h3()"
></pm-button></div>
<!-- next -->
<div
[attr.class]="e18()"
data-lightbox-part="next"
><pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e15()"
icon="next"
[label]="e19()"
[disabled]="e20()"
(click)="h4()"
></pm-button></div>
<!-- position -->
<p
[attr.class]="e21()"
role="status"
>{{ e22() }}</p>}
<!-- close -->
<div
[attr.class]="e23()"
data-dialog-part="close"
><pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e24()"
icon="close"
[label]="e25()"
(click)="h5()"
></pm-button></div></div></div>}</ng-template>`,
})
export class Lightbox {
  /**
   * The picture shown first while the lightbox holds the position. Defaults to 0.
   */
  readonly defaultIndex = input<
    Exclude<LightboxProps['defaultIndex'], undefined>,
    LightboxProps['defaultIndex']
  >(0, { transform: (value: LightboxProps['defaultIndex']) => (value === undefined ? 0 : value) })
  readonly defaultOpen = input<LightboxProps['defaultOpen']>(undefined)
  /**
   * The pictures in reading order. An empty list opens nothing.
   */
  readonly images = input.required<LightboxProps['images']>()
  /**
   * The picture shown, counted from 0. Controlled, as in Carousel.
   */
  readonly index = input<LightboxProps['index']>(undefined)
  /**
   * The dialog's accessible name, such as "Attachment preview". It is not drawn.
   */
  readonly label = input.required<LightboxProps['label']>()
  /**
   * Omit for the English defaults; localized hosts pass their own.
   */
  readonly messages = input<
    Exclude<LightboxProps['messages'], undefined>,
    LightboxProps['messages']
  >(
    (() => ({
      close: 'Close',
      previous: 'Previous picture',
      next: 'Next picture',
      position: (position, count) => `${position} of ${count}`,
    }))(),
    {
      transform: (value: LightboxProps['messages']) =>
        value === undefined
          ? (() => ({
              close: 'Close',
              previous: 'Previous picture',
              next: 'Next picture',
              position: (position, count) => `${position} of ${count}`,
            }))()
          : value,
    },
  )
  readonly open = input<LightboxProps['open']>(undefined)
  /**
   * Called with the index of the picture the reader moved to.
   */
  readonly onIndexChange = output<number>({ alias: 'indexChange' })
  readonly onOpenChange = output<boolean>({ alias: 'openChange' })
  protected readonly $ = useMember({
    events: ['indexChange', 'openChange'],
    props: {
      defaultIndex: () => this.defaultIndex(),
      defaultOpen: () => this.defaultOpen(),
      images: () => this.images(),
      index: () => this.index(),
      label: () => this.label(),
      messages: () => this.messages(),
      open: () => this.open(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly opener = cell(() => null as HTMLElement | null)
  protected readonly mirror = cell(() => this.$p.defaultIndex)
  protected readonly panel = elementRef<HTMLElement>()
  protected readonly scrim = elementRef<HTMLElement>()
  protected readonly within = derived(
    () => (at: number) => Math.min(Math.max(at, 0), Math.max(this.$p.images.length - 1, 0)),
  )
  protected readonly shown = derived(() => this.within.value(this.$p.index ?? this.mirror.value))
  protected readonly several = derived(() => this.$p.images.length > 1)
  protected readonly current = derived(() =>
    this.$p.images.slice(this.shown.value, this.shown.value + 1),
  )
  protected readonly travel = derived(() => (to: number) => {
    if (to < 0 || to >= this.$p.images.length || to === this.shown.value) return
    this.mirror.value = to
    this.$.emit(this.onIndexChange, 'onIndexChange', to)
  })
  protected readonly keyDown = derived(() => (event: KeyboardEvent) => {
    if (!this.several.value || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey)
      return
    const rtl = getComputedStyle(event.currentTarget as HTMLElement).direction === 'rtl'
    const forward = rtl ? 'ArrowLeft' : 'ArrowRight'
    const back = rtl ? 'ArrowRight' : 'ArrowLeft'
    if (event.key !== forward && event.key !== back) return
    event.preventDefault()
    this.travel.value(event.key === forward ? this.shown.value + 1 : this.shown.value - 1)
  })
  protected readonly focusAfterMove = derived(() => () => {
    if (this.panel.value === null) return
    const previous = this.panel.value.querySelector<HTMLButtonElement>(
      '[data-lightbox-part="previous"] button',
    )
    const next = this.panel.value.querySelector<HTMLButtonElement>(
      '[data-lightbox-part="next"] button',
    )
    const active = document.activeElement
    const lost =
      active === null ||
      active === document.body ||
      ((active === previous || active === next) && (active as HTMLButtonElement).disabled)
    if (!lost) return
    const other = [previous, next].find((button) => button !== null && !button.disabled)
    other?.focus()
  })
  protected readonly documentDirection = useDirection()
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () =>
        ({
          id: this.uid,
          dir: this.documentDirection(),
          open: this.$p.open === undefined ? undefined : this.$p.open && this.$p.images.length > 0,
          defaultOpen:
            this.$p.defaultOpen === undefined
              ? undefined
              : this.$p.defaultOpen && this.$p.images.length > 0,
          initialFocusEl: () => modalFocusTarget(this.panel.value, 'primary'),
          finalFocusEl: () => this.opener.value,
          onOpenChange: (details) => {
            this.$.emit(this.onOpenChange, 'onOpenChange', details.open)
          },
        }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )
  protected readonly openFrom = derived(() => (event?: Event) => {
    if (this.$p.images.length === 0) return
    if (event?.currentTarget instanceof HTMLElement) this.opener.value = event.currentTarget
    this.api.value.setOpen(true)
  })
  protected readonly scrimPresent = setup(() =>
    usePresence(
      () => this.api.value.open,
      () => this.scrim.value,
      'dialog.scrim',
    ),
  )
  protected readonly panelPresent = setup(() =>
    usePresence(
      () => this.api.value.open,
      () => this.panel.value,
      'dialog.panel',
    ),
  )
  private release2: (() => void) | undefined

  constructor() {
    this.$.pass('trigger', () => ({ onClick: this.openFrom.value }))
    watchEffect(
      () => this.shown.value,
      () => this.effect1(),
      false,
    )
    inject(DestroyRef).onDestroy(() => this.release2?.())
    mountEffect(() => this.effect2())
  }

  protected e1() {
    return this.scrimPresent.value()
  }

  protected h1(): void {
    if (!this.scrimPresent.value()) return
    this.api.value.setOpen(false)
  }

  protected e2() {
    if (!this.scrimPresent.value()) return undefined as never
    return mergeParts(this.api.value.getBackdropProps(), {
      class: styles.scrim,
      hidden: undefined,
      onClick: () => this.h1(),
    })
  }

  protected e3() {
    return this.panelPresent.value()
  }

  protected e4() {
    if (!this.panelPresent.value()) return undefined as never
    return mergeParts(this.api.value.getPositionerProps(), { class: styles.positioner })
  }

  protected h2($event: KeyboardEvent): void {
    if (!this.panelPresent.value()) return
    this.keyDown.value($event)
  }

  protected e5() {
    if (!this.panelPresent.value()) return undefined as never
    return mergeParts(this.api.value.getContentProps(), {
      class: styles.panel,
      hidden: undefined,
      'data-member': 'lightbox',
      onKeydown: ($event: KeyboardEvent) => this.h2($event),
    })
  }

  protected e6() {
    if (!this.panelPresent.value()) return undefined as never
    return mergeParts(this.api.value.getTitleProps(), { class: styles.title })
  }

  protected e7() {
    if (!this.panelPresent.value()) return undefined as never
    return this.$p.label
  }

  protected e8() {
    if (!this.panelPresent.value()) return undefined as never
    return styles.stage
  }

  e9() {
    if (!this.panelPresent.value()) return undefined as never
    return this.current.value
  }

  protected e10() {
    return this.shown.value
  }

  protected e11(picture: Each<ReturnType<Lightbox['e9']>>): ImageProps['src'] {
    if (!this.panelPresent.value()) return undefined as never
    return picture.src
  }

  protected e12(picture: Each<ReturnType<Lightbox['e9']>>): ImageProps['alt'] {
    if (!this.panelPresent.value()) return undefined as never
    return picture.alt
  }

  protected e13() {
    if (!this.panelPresent.value()) return undefined as never
    return this.several.value
  }

  protected e14() {
    if (!this.panelPresent.value()) return undefined as never
    if (!this.several.value) return undefined as never
    return styles.previous
  }

  protected e15(): ButtonProps['iconOnly'] {
    if (!this.panelPresent.value()) return undefined as never
    if (!this.several.value) return undefined as never
    return true
  }

  protected e16(): ButtonProps['label'] {
    if (!this.panelPresent.value()) return undefined as never
    if (!this.several.value) return undefined as never
    return this.$p.messages.previous
  }

  protected e17(): ButtonProps['disabled'] {
    if (!this.panelPresent.value()) return undefined as never
    if (!this.several.value) return undefined as never
    return this.shown.value === 0
  }

  protected h3(): void {
    if (!this.panelPresent.value()) return
    if (!this.several.value) return
    this.travel.value(this.shown.value - 1)
  }

  protected e18() {
    if (!this.panelPresent.value()) return undefined as never
    if (!this.several.value) return undefined as never
    return styles.next
  }

  protected e19(): ButtonProps['label'] {
    if (!this.panelPresent.value()) return undefined as never
    if (!this.several.value) return undefined as never
    return this.$p.messages.next
  }

  protected e20(): ButtonProps['disabled'] {
    if (!this.panelPresent.value()) return undefined as never
    if (!this.several.value) return undefined as never
    return this.shown.value === this.$p.images.length - 1
  }

  protected h4(): void {
    if (!this.panelPresent.value()) return
    if (!this.several.value) return
    this.travel.value(this.shown.value + 1)
  }

  protected e21() {
    if (!this.panelPresent.value()) return undefined as never
    if (!this.several.value) return undefined as never
    return styles.position
  }

  protected e22() {
    if (!this.panelPresent.value()) return undefined as never
    if (!this.several.value) return undefined as never
    return this.$p.messages.position(this.shown.value + 1, this.$p.images.length)
  }

  protected e23() {
    if (!this.panelPresent.value()) return undefined as never
    return styles.close
  }

  protected e24(): ButtonProps['iconOnly'] {
    if (!this.panelPresent.value()) return undefined as never
    return true
  }

  protected e25(): ButtonProps['label'] {
    if (!this.panelPresent.value()) return undefined as never
    return this.$p.messages.close
  }

  protected h5(): void {
    if (!this.panelPresent.value()) return
    this.api.value.setOpen(false)
  }

  private effect1(): void {
    this.focusAfterMove.value()
  }

  private effect2(): void {
    this.release2?.()
    const ran = agentMember({
      member: 'Lightbox',
      element: () => this.panel.value,
      state: () => ({
        open: this.api.value.open,
        index: this.shown.value,
        images: this.$p.images.map((image) => ({ alt: image.alt })),
      }),
      actions: {
        close: () => this.api.value.open && this.api.value.setOpen(false),
        next: () =>
          (() => {
            if (!this.api.value.open) throw new Error('The lightbox is closed.')
            if (this.shown.value === this.$p.images.length - 1)
              throw new Error('This is the last picture.')
            this.travel.value(this.shown.value + 1)
          })(),
        previous: () =>
          (() => {
            if (!this.api.value.open) throw new Error('The lightbox is closed.')
            if (this.shown.value === 0) throw new Error('This is the first picture.')
            this.travel.value(this.shown.value - 1)
          })(),
      },
      withholds: () => this.panel.value,
    })
    this.release2 = () => {
      ran()
    }
  }
}
